function Page_TutorialsGuide(params){const _root=document.createDocumentFragment();const _e3395=WF.el("div",{className:"wf-stack wf-gap--lg"});const _e3396=WF.el("div",{className:"wf-markdown",markdown:"Three projects, each built step by step and each complete in the repository under `examples/tutorials/`. None needs a server: what they keep, they keep in the reader's browser. Pick the one that matches where you are — each stands on its own — or do them in order."});_e3395.appendChild(_e3396);const _e3397=WF.el("table",{className:"wf-table"},WF.el("caption",{className:"wf-visually-hidden"},"Tutorials"));const _e3398=WF.el("thead",{});const _e3399=WF.el("tr",{});const _e3400=WF.el("th",{scope:"col"},"");_e3399.appendChild(_e3400);const _e3401=WF.el("th",{scope:"col"},"Project");_e3399.appendChild(_e3401);const _e3402=WF.el("th",{scope:"col"},"What you build");_e3399.appendChild(_e3402);const _e3403=WF.el("th",{scope:"col"},"What it teaches");_e3399.appendChild(_e3403);const _e3404=WF.el("th",{scope:"col"},"Time");_e3399.appendChild(_e3404);_e3398.appendChild(_e3399);_e3397.appendChild(_e3398);const _e3405=WF.el("tbody",{});const _e3406=WF.el("tr",{});const _e3407=WF.el("td",{});const _e3408=WF.el("div",{className:"wf-markdown",markdown:"**Easy**"});_e3407.appendChild(_e3408);_e3406.appendChild(_e3407);const _e3409=WF.el("td",{});const _e3410=WF.el("div",{className:"wf-markdown",markdown:"[Todos](#easy-todos)"});_e3409.appendChild(_e3410);_e3406.appendChild(_e3409);const _e3411=WF.el("td",{},"A list of things to do: add, tick, rename, filter");_e3406.appendChild(_e3411);const _e3412=WF.el("td",{});const _e3413=WF.el("div",{className:"wf-markdown",markdown:"Types, a store with `persist`, a component, a keyed list, a filter in the address, tests that click"});_e3412.appendChild(_e3413);_e3406.appendChild(_e3412);const _e3414=WF.el("td",{},"20 minutes");_e3406.appendChild(_e3414);_e3405.appendChild(_e3406);const _e3415=WF.el("tr",{});const _e3416=WF.el("td",{});const _e3417=WF.el("div",{className:"wf-markdown",markdown:"**Medium**"});_e3416.appendChild(_e3417);_e3415.appendChild(_e3416);const _e3418=WF.el("td",{});const _e3419=WF.el("div",{className:"wf-markdown",markdown:"[Field Notes](#medium-field-notes)"});_e3418.appendChild(_e3419);_e3415.appendChild(_e3418);const _e3420=WF.el("td",{},"A notebook site, statically built, a page per note");_e3415.appendChild(_e3420);const _e3421=WF.el("td",{});const _e3422=WF.el("div",{className:"wf-markdown",markdown:"`data` files, a layout, `:slug` pages with `paths:`, Markdown pages, search and tags, what a static page can know"});_e3421.appendChild(_e3422);_e3415.appendChild(_e3421);const _e3423=WF.el("td",{},"An hour");_e3415.appendChild(_e3423);_e3405.appendChild(_e3415);const _e3424=WF.el("tr",{});const _e3425=WF.el("td",{});const _e3426=WF.el("div",{className:"wf-markdown",markdown:"**Hard**"});_e3425.appendChild(_e3426);_e3424.appendChild(_e3425);const _e3427=WF.el("td",{});const _e3428=WF.el("div",{className:"wf-markdown",markdown:"[Pocket](#hard-pocket)"});_e3427.appendChild(_e3428);_e3424.appendChild(_e3427);const _e3429=WF.el("td",{},"A budget tracker with a dashboard, forms and two languages");_e3424.appendChild(_e3429);const _e3430=WF.el("td",{});const _e3431=WF.el("div",{className:"wf-markdown",markdown:"`Money` and `Date`, derived totals, a `persist` migration, `validate`, a dialog and shortcuts, i18n and RTL, a script of your own, offline"});_e3430.appendChild(_e3431);_e3424.appendChild(_e3430);const _e3432=WF.el("td",{},"A couple of hours");_e3424.appendChild(_e3432);_e3405.appendChild(_e3424);_e3397.appendChild(_e3405);_e3395.appendChild(_e3397);const _e3433=WF.el("div",{className:"wf-markdown",markdown:"Every block that names a file — `// src/stores/Todos.wf` on its first line — is that file, or a run of it, word for word: a test holds the chapter to the projects. To start from a finished one:"});_e3395.appendChild(_e3433);const _e3434=Component_Terminal({lines:[({command:"git clone https://github.com/monzeromer-lab/WebFluent",output:""}),({command:"cd WebFluent/examples/tutorials/easy-todos",output:""}),({command:"wf serve",output:""})]});_e3395.appendChild(_e3434);const _e3435=WF.el("div",{className:"wf-markdown",markdown:"If you have not written WebFluent before, [the Shelf tutorial](/docs/guide/tutorial) is a gentler first half hour."});_e3395.appendChild(_e3435);const _e3436=WF.el("h2",{className:"wf-heading",id:"easy-todos"},"Easy: Todos");_e3395.appendChild(_e3436);const _e3437=WF.el("div",{className:"wf-markdown",markdown:"A list of things to do, kept in the reader's browser: add one, tick it, rename it, remove it, show the open ones. One page, one store, one component — about twenty minutes. The finished project is [`examples/tutorials/easy-todos`](https://github.com/monzeromer-lab/WebFluent/tree/master/examples/tutorials/easy-todos)."});_e3395.appendChild(_e3437);const _e3438=WF.el("h3",{className:"wf-heading",id:"step-1-a-project"},"Step 1: a project");_e3395.appendChild(_e3438);const _e3439=Component_Terminal({lines:[({command:"wf init todos -t spa",output:""}),({command:"cd todos",output:""})]});_e3395.appendChild(_e3439);const _e3440=WF.el("div",{className:"wf-markdown",markdown:"Delete what the template put in `src/` — you write every file yourself — and replace `webfluent.app.json`:"});_e3395.appendChild(_e3440);const _e3441=Component_CodeBlock({code:"{\n  \"name\": \"todos\",\n  \"version\": \"1.0.0\",\n  \"theme\": { \"name\": \"Paper\", \"dark\": \"Night\" },\n  \"build\": { \"output\": \"./build\", \"output_type\": \"spa\", \"csp\": true },\n  \"meta\": {\n    \"title\": \"Todos\",\n    \"description\": \"A small list of things to do, kept in your browser.\",\n    \"lang\": \"en\",\n    \"favicon\": \"/favicon.svg\"\n  }\n}",title:"json"});_e3395.appendChild(_e3441);const _e3442=WF.el("div",{className:"wf-markdown",markdown:"`spa` is a single-page app: one HTML shell, pages swapped without a reload ([Static sites and SPAs](/docs/guide/static-and-spa)). `csp` ships a content security policy and holds the build to it ([Security](/docs/guide/security)). Run `wf serve` in another terminal and leave it running: every save rebuilds and reloads the page."});_e3395.appendChild(_e3442);const _e3443=WF.el("h3",{className:"wf-heading",id:"step-2-what-a-todo-is"},"Step 2: what a todo is");_e3395.appendChild(_e3443);const _e3444=Component_CodeBlock({code:"// src/types.wf\n/// One thing to do.\ntype Todo {\n    id: Uuid\n    title: String\n    done: Bool = false\n}\n\n/// Which todos the list shows.\nenum Filter { all, open, done }",title:"wf"});_e3395.appendChild(_e3444);const _e3445=WF.el("div",{className:"wf-markdown",markdown:"A `type` names the fields a value has, and the checker holds every use to them: `todo.titel` is an error where it is written, with the field you meant ([Types](/docs/guide/types)). `Uuid` is one of the types the language brings; `uuid()` makes one. `done` has a default, so a new todo can leave it out. An `enum` is a fixed set of cases, written `.open` where a `Filter` is wanted."});_e3395.appendChild(_e3445);const _e3446=WF.el("h3",{className:"wf-heading",id:"step-3-a-store-that-remembers"},"Step 3: a store that remembers");_e3395.appendChild(_e3446);const _e3447=Component_CodeBlock({code:"// src/stores/Todos.wf\n/// The list, kept in the browser between visits.\nstore Todos {\n    persist items: [Todo] = []\n\n    derived open = items.filter(t => !t.done)\n    derived done = items.filter(t => t.done)\n\n    action add(title: String) {\n        let text = title.trim()\n        if text == \"\" { return }\n        items = items.concat([Todo(id: uuid(), title: text)])\n    }\n\n    action toggle(id: Uuid) {\n        items = items.map(t => if t.id == id { { ...t, done: !t.done } } else { t })\n    }",title:"wf"});_e3395.appendChild(_e3447);const _e3448=WF.el("div",{className:"wf-markdown",markdown:"A store is state any page or component can read ([Stores](/docs/guide/stores)). `persist` is `state` that is kept in the browser's storage: the list is there after a reload, and a second tab follows the first, with no storage code written. `derived` values follow what they read — `open` is always the todos not done. An action is the only place state changes; `{ ...t, done: !t.done }` is the todo with one field changed.\n\nThe rest of the store renames, removes and clears in the same way — see the [whole file](https://github.com/monzeromer-lab/WebFluent/blob/master/examples/tutorials/easy-todos/src/stores/Todos.wf)."});_e3395.appendChild(_e3448);const _e3449=WF.el("h3",{className:"wf-heading",id:"step-4-one-row"},"Step 4: one row");_e3395.appendChild(_e3449);const _e3450=Component_CodeBlock({code:"// src/components/TodoRow.wf\n/// One row of the list: a box to tick, the title, and buttons to rename and\n/// remove it.\ncomponent TodoRow(_ todo: Todo) {\n    use Todos\n    state editing = false\n    state draft = todo.title\n\n    action save() {\n        Todos.rename(todo.id, draft)\n        editing = false\n    }\n\n    Row(class: [\"todo\", if todo.done { \"is-done\" }], align: .center, gap: .sm) {\n        Checkbox(checked: todo.done, aria-label: \"Done: {todo.title}\") {\n            on change { Todos.toggle(todo.id) }\n        }\n        if editing {\n            // `mount:` runs when the input is made: the cursor goes straight in.\n            Input(bind: draft, aria-label: \"New title for {todo.title}\", class: \"todo__edit\", mount: (n) => n.focus()) {\n                on key(\"Enter\") { save() }\n                on key(\"Escape\") { draft = todo.title  editing = false }\n                on blur { save() }\n            }\n        } else {\n            Text(todo.title, class: \"todo__title\")\n            IconButton(icon: \"edit\", label: \"Rename {todo.title}\", class: \"todo__action\").sm {\n                on click { draft = todo.title  editing = true }\n            }\n        }\n        IconButton(icon: \"trash\", label: \"Remove {todo.title}\", class: \"todo__action\").sm {\n            on click { Todos.remove(todo.id) }\n        }\n    }\n}",title:"wf"});_e3395.appendChild(_e3450);const _e3451=WF.el("div",{className:"wf-markdown",markdown:"A component is an element of your own ([Components](/docs/guide/components)). `_ todo` is its one positional prop, so a call reads `TodoRow(todo)`. Its `state` belongs to each row: one row being renamed does not put the others in edit mode. `class:` adds classes to the element's own — a list may hold an `if`, which adds `is-done` only while the todo is done. Every control has an accessible name: the checkbox and the icon buttons say which todo they act on, so a screen reader — and the tests in step 7 — can tell them apart ([Accessibility](/docs/guide/accessibility))."});_e3395.appendChild(_e3451);const _e3452=WF.el("h3",{className:"wf-heading",id:"step-5-the-page"},"Step 5: the page");_e3395.appendChild(_e3452);const _e3453=Component_CodeBlock({code:"// src/pages/Home.wf\npage Home(path: \"/\", title: \"Todos\", description: \"A small list of things to do, kept in your browser.\") {\n    use Todos\n    state draft = \"\"\n\n    // The filter lives in the address — `/?show=open` — so a reload or a\n    // shared link keeps it.\n    derived filter: Filter = if query.show == \"open\" { .open } else if query.show == \"done\" { .done } else { .all }\n    derived shown = match filter {\n        .open { Todos.open }\n        .done { Todos.done }\n        .all { Todos.items }\n    }\n\n    action add() {\n        Todos.add(draft)\n        draft = \"\"\n    }\n\n    Stack(class: \"card\", gap: .md) {\n        Row(justify: .between, align: .baseline) {\n            Heading(\"Todos\").h1\n            Text(\"{Todos.open.length} left\", class: \"count\")\n        }\n\n        Row(class: \"new\", gap: .sm) {\n            Input(bind: draft, placeholder: \"What needs doing?\", aria-label: \"New todo\") {\n                on key(\"Enter\") { add() }\n            }\n            Button(\"Add\", disabled: draft.trim() == \"\").primary {\n                on click { add() }\n            }\n        }",title:"wf"});_e3395.appendChild(_e3453);const _e3454=WF.el("div",{className:"wf-markdown",markdown:"`bind: draft` ties the input to the state both ways: typing changes `draft`, and `draft = \"\"` empties the box. `query` is the address's query string as a value, kept current, so `filter` follows the address and `shown` follows `filter`. A `match` over an enum must cover every case — a fourth filter added to `Filter` would be an error here until it is handled. The rest of the page draws the list:"});_e3395.appendChild(_e3454);const _e3455=Component_CodeBlock({code:"// src/pages/Home.wf\n        Row(class: \"filters\", gap: .xs, align: .center) {\n            Link(\"All\", to: \"/?show=all\", class: { \"is-on\": filter == .all })\n            Link(\"Open\", to: \"/?show=open\", class: { \"is-on\": filter == .open })\n            Link(\"Done\", to: \"/?show=done\", class: { \"is-on\": filter == .done })\n            Spacer\n            if Todos.done.length > 0 {\n                Button(\"Clear done\").sm {\n                    on click { Todos.clearDone() }\n                }\n            }\n        }\n\n        if shown.length == 0 {\n            Text(if Todos.items.length == 0 { \"Nothing yet — add your first todo above.\" } else { \"Nothing here.\" }, class: \"empty\")\n        }\n        Stack(class: \"list\") {\n            for todo in shown by todo.id {\n                TodoRow(todo, animate: .fadeIn, exit: .fadeOut)\n            }\n        }\n    }",title:"wf"});_e3395.appendChild(_e3455);const _e3456=WF.el("div",{className:"wf-markdown",markdown:"`for … by todo.id` is a keyed list: when a todo is ticked away by the filter or renamed, only its row changes — the others keep their nodes, and the row being edited keeps its cursor ([Control flow](/docs/guide/control-flow)). `animate:` and `exit:` fade a row in and out. A class map, `{ \"is-on\": filter == .all }`, turns a class on while its condition holds.\n\nAnd the frame every page sits in:"});_e3395.appendChild(_e3456);const _e3457=Component_CodeBlock({code:"// src/App.wf\n// The frame every page sits in: a narrow column, centred.\napp {\n    Container(class: \"shell\") {\n        Router\n    }\n}",title:"wf"});_e3395.appendChild(_e3457);const _e3458=WF.el("h3",{className:"wf-heading",id:"step-6-a-look-of-its-own"},"Step 6: a look of its own");_e3395.appendChild(_e3458);const _e3459=Component_CodeBlock({code:"// src/theme.wf\n/// Warm paper and ink, with one teal for what you can act on.\ntheme Paper {\n    color-primary: #0F766E\n    color-background: #F6F4EF\n    color-surface: #FFFFFF\n    color-text: #1F2328\n    color-text-muted: #5E6670\n    color-border: #E4E0D8\n    font-family: system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif\n    radius-md: 10px\n}",title:"wf"});_e3395.appendChild(_e3459);const _e3460=WF.el("div",{className:"wf-markdown",markdown:"A theme names only the design tokens it changes ([Styling](/docs/guide/styling)); `Night`, named as `\"dark\"` in the config, is used when the reader's system is dark. The classes the page names — `card`, `todo`, `is-done`, `filters` — are styled in `src/todos.css`, which the build bundles because it is under `src/`:"});_e3395.appendChild(_e3460);const _e3461=Component_CodeBlock({code:".todo { flex-wrap: nowrap; padding: 0.6rem 0.25rem; border-top: 1px solid var(--color-border); }\n.todo__title { flex: 1; }\n.todo.is-done .todo__title { text-decoration: line-through; color: var(--color-text-muted); }\n.filters a.is-on { background: var(--color-background); color: var(--color-text); font-weight: 600; }",title:"css"});_e3395.appendChild(_e3461);const _e3462=WF.el("h3",{className:"wf-heading",id:"step-7-tests"},"Step 7: tests");_e3395.appendChild(_e3462);const _e3463=Component_CodeBlock({code:"// tests/todos.wf\ntest \"adding a todo puts it in the list\" {\n    use Todos\n    state draft = \"\"\n    Input(bind: draft, aria-label: \"New todo\")\n    Button(\"Add\") { on click { Todos.add(draft)  draft = \"\" } }\n    for t in Todos.items by t.id { TodoRow(t) }\n    Text(\"{Todos.open.length} left\")\n\n    expect \"0 left\"\n    type \"Buy bread\" into \"New todo\"\n    click \"Add\"\n    expect \"Buy bread\"\n    expect \"1 left\"\n}",title:"wf"});_e3395.appendChild(_e3463);const _e3464=WF.el("div",{className:"wf-markdown",markdown:"A test draws what it declares and then follows its steps in order: it types into the control named \"New todo\" and clicks the button named \"Add\", the way a reader would, in a headless Chrome ([Testing](/docs/guide/testing)). `wf test` runs every test under `tests/`; the project has six — a blank todo is refused, ticking and clearing empties the list, renaming keeps one row for each."});_e3395.appendChild(_e3464);const _e3465=WF.el("h3",{className:"wf-heading",id:"step-8-build-it"},"Step 8: build it");_e3395.appendChild(_e3465);const _e3466=Component_Terminal({lines:[({command:"wf check",output:""}),({command:"wf test",output:""}),({command:"wf build",output:""})]});_e3395.appendChild(_e3466);const _e3467=WF.el("div",{className:"wf-markdown",markdown:"`wf check` reports every finding with nothing written; `wf build` writes `build/`, which any static host serves — [Deploying](/docs/guide/deploying) has GitHub Pages, Netlify and the rest. `wf verify` loads the built page in a real browser and fails on an error, a missing file or a page that draws nothing."});_e3395.appendChild(_e3467);const _e3468=WF.el("h2",{className:"wf-heading",id:"medium-field-notes"},"Medium: Field Notes");_e3395.appendChild(_e3468);const _e3469=WF.el("div",{className:"wf-markdown",markdown:"A notebook kept in public — notes from a garden, a kitchen and a few trips — built as a static site. The notes are a JSON file read when the site is built; every page, one per note included, is written out as HTML a search engine reads; the one thing a reader changes, the notes they save for later, stays in their browser. About an hour. The finished project is [`examples/tutorials/medium-field-notes`](https://github.com/monzeromer-lab/WebFluent/tree/master/examples/tutorials/medium-field-notes)."});_e3395.appendChild(_e3469);const _e3470=WF.el("h3",{className:"wf-heading",id:"step-1-a-static-project-and-its-look"},"Step 1: a static project and its look");_e3395.appendChild(_e3470);const _e3471=Component_Terminal({lines:[({command:"wf init field-notes -t static",output:""}),({command:"cd field-notes",output:""})]});_e3395.appendChild(_e3471);const _e3472=Component_CodeBlock({code:"{\n  \"name\": \"field-notes\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Field Notes\",\n  \"theme\": { \"name\": \"Meadow\", \"dark\": \"Dusk\" },\n  \"build\": {\n    \"output\": \"./build\",\n    \"ssg\": true,\n    \"csp\": true\n  },\n  \"meta\": {\n    \"title\": \"Field Notes\",\n    \"description\": \"Notes from a small garden, a busy kitchen and the roads between them.\",\n    \"lang\": \"en\",\n    \"site_url\": \"https://field-notes.example.com\",\n    \"site_name\": \"Field Notes\",\n    \"favicon\": \"/favicon.svg\",\n    \"image\": \"/card.png\",\n    \"sitemap\": true\n  }\n}",title:"json"});_e3395.appendChild(_e3472);const _e3473=WF.el("div",{className:"wf-markdown",markdown:"`ssg` pre-renders every page to its own `index.html`, and the script takes the page over when it loads ([Static sites and SPAs](/docs/guide/static-and-spa)). `site_url` lets the build write what search engines and link previews read: a canonical address, Open Graph tags, JSON-LD, `sitemap.xml` and `robots.txt` ([Content](/docs/guide/content))."});_e3395.appendChild(_e3473);const _e3474=Component_CodeBlock({code:"// src/theme.wf\n/// The dark theme: only the tokens that change.\ntheme Dusk {\n    color-primary: #86C9A6\n    color-secondary: #E8A086\n    color-background: #121614\n    color-surface: #1A201D\n    color-text: #E9E5DA\n    color-text-muted: #A6AFA9\n    color-border: #2B3430\n    paper-raised: #171C19\n    tag-bg: #213129\n    tag-text: #A9DCC1\n}",title:"wf"});_e3395.appendChild(_e3474);const _e3475=WF.el("div",{className:"wf-markdown",markdown:"The light theme, `Meadow`, sets the same names. A theme may declare tokens of its own — `paper-raised`, `tag-bg` — and the project's stylesheet, `src/styles.css`, reads every colour as a token (`var(--tag-bg)`), so the dark theme needs no rule of its own ([Design tokens](/docs/guide/tokens))."});_e3395.appendChild(_e3475);const _e3476=WF.el("h3",{className:"wf-heading",id:"step-2-typed-data"},"Step 2: typed data");_e3395.appendChild(_e3476);const _e3477=Component_CodeBlock({code:"// src/types.wf\n/// One note in the notebook.\ntype Note {\n    slug: String\n    title: String\n    date: Date\n    tags: [String]\n    summary: String\n    minutes: Number\n    body: String\n}\n\n/// Every note, read from `notes.json` when the site is built.\ndata notes: [Note] = \"notes.json\"",title:"wf"});_e3395.appendChild(_e3477);const _e3478=WF.el("div",{className:"wf-markdown",markdown:"`data` reads a JSON file at build time: it is a constant, typed by the annotation, inlined into the bundle and seeded into every pre-rendered page ([Data](/docs/guide/data)). The checker holds the program to `Note`: a page that reads `note.titel` is an error where it is written. `date` is a `Date`, a plain `\"2026-03-08\"` string the language knows how to format — `{note.date:.date(long)}` is \"March 8, 2026\". `src/notes.json` holds seven notes, each with a Markdown `body`."});_e3395.appendChild(_e3478);const _e3479=WF.el("h3",{className:"wf-heading",id:"step-3-the-shell-and-a-layout"},"Step 3: the shell and a layout");_e3395.appendChild(_e3479);const _e3480=Component_CodeBlock({code:"// src/App.wf\napp {\n    use Saved\n\n    Navbar(class: \"site-nav\") {\n        Navbar.Brand {\n            Link(\"Field Notes\", to: \"/\", class: \"brand\")\n        }\n        Navbar.Links {\n            Link(\"Notes\", to: \"/\")\n            Link(\"Tags\", to: \"/tags\")\n            Link(to: \"/saved\", class: \"saved-link\") {\n                Text(\"Saved\")\n                if Saved.count > 0 {\n                    Badge(\"{Saved.count}\").pill\n                }\n            }\n            Link(\"About\", to: \"/about\")\n        }\n        Navbar.Actions {\n            ThemeToggle\n        }\n    }\n\n    Router(transition: .fade, duration: \"160ms\")",title:"wf"});_e3395.appendChild(_e3480);const _e3481=WF.el("div",{className:"wf-markdown",markdown:"`app` is what wraps every page; the current page is drawn where `Router` stands, inside `<main>`, so the skip link a page carries jumps past the navigation ([Pages and routing](/docs/guide/pages-and-routing)). The link whose `to:` is the page shown is marked `aria-current=\"page\"`. Each page names the column it is set in with `layout:` — a component whose default slot is the page:"});_e3395.appendChild(_e3481);const _e3482=Component_CodeBlock({code:"// src/components/Sheet.wf\n/// The column a page is set in, and the frame every page names with\n/// `layout: Sheet`. A narrow sheet is for reading; a wide one holds a grid.\ncomponent Sheet(wide: Bool = false) {\n    slot\n    Container(class: [\"sheet\", if wide { \"sheet--wide\" }]) {\n        children\n    }\n}",title:"wf"});_e3395.appendChild(_e3482);const _e3483=WF.el("div",{className:"wf-markdown",markdown:"`ThemeToggle` is two icon buttons that call `setTheme(\"dark\")` and `setTheme(\"light\")`; the choice is kept across visits."});_e3395.appendChild(_e3483);const _e3484=WF.el("h3",{className:"wf-heading",id:"step-4-a-card"},"Step 4: a card");_e3395.appendChild(_e3484);const _e3485=Component_CodeBlock({code:"// src/components/NoteCard.wf\n/// A note at a glance: when it was written, its title, a summary, its tags\n/// and the button that saves it.\ncomponent NoteCard(\n    _ note: Note,\n    /// Keeps the card in the page but out of sight — what a filter does.\n    hidden: Bool = false\n) {\n    Card(class: \"note-card\", hidden: hidden) {\n        Stack(gap: .sm) {\n            Row(justify: .between, align: .center, gap: .sm) {\n                Text(\"{note.date:.date(long)} · {note.minutes} min read\", class: \"note-meta\").sm\n                SaveButton(note.slug, title: note.title)\n            }\n            Link(to: \"/notes/{note.slug}\", class: \"note-card__link\") {\n                Heading(note.title).h2\n            }\n            Text(note.summary, class: \"note-card__summary\")\n            TagList(note.tags)\n        }\n    }\n}",title:"wf"});_e3395.appendChild(_e3485);const _e3486=WF.el("div",{className:"wf-markdown",markdown:"A `///` comment above a component or a prop is its documentation, shown when the editor hovers a call ([Components](/docs/guide/components)). A splice may say how to show its value: `{note.date:.date(long)}` is `format(note.date, .date, \"long\")` written where it is read ([Expressions](/docs/guide/expressions)). `TagList` is a row of `#tag` links to `/?tag=…`."});_e3395.appendChild(_e3486);const _e3487=WF.el("h3",{className:"wf-heading",id:"step-5-the-front-page-a-search-and-a-filter-in-the-address"},"Step 5: the front page — a search and a filter in the address");_e3395.appendChild(_e3487);const _e3488=Component_CodeBlock({code:"// src/components/NoteFinder.wf\n    state q = \"\"\n\n    derived needle = q.trim().toLowerCase()\n    derived newest = all.sortBy(n => n.date).reverse()\n    derived shown = newest.filter(n =>\n        (tag == \"\" || n.tags.includes(tag))\n        && (needle == \"\"\n            || n.title.toLowerCase().includes(needle)\n            || n.summary.toLowerCase().includes(needle)))\n    derived visible = shown.map(n => n.slug)\n    derived allTags = all.flatMap(n => n.tags).unique().sort()",title:"wf"});_e3395.appendChild(_e3488);const _e3489=WF.el("div",{className:"wf-markdown",markdown:"`q` is bound to the search box; everything else follows it. `sortBy`, `flatMap` and `unique` are list helpers the language brings, and each runs at build time too, so the pre-rendered page shows the sorted list ([State and reactivity](/docs/guide/state))."});_e3395.appendChild(_e3489);const _e3490=Component_CodeBlock({code:"// src/components/NoteFinder.wf\n            // Every note is drawn, and the ones that do not match are hidden.\n            // A pre-rendered page cannot know the URL's query, so a list\n            // filtered by it would be missing from the HTML; this way the\n            // page carries every note, and the filter applies once it is live.\n            for note in newest by note.slug {\n                NoteCard(note, hidden: !visible.includes(note.slug))\n            }",title:"wf"});_e3395.appendChild(_e3490);const _e3491=WF.el("div",{className:"wf-markdown",markdown:"This is the one idea a static site adds: the HTML is written once, before any reader arrives, so it cannot depend on what only the browser knows — the address's query, what is in storage. Drawing every note and hiding the misses means the HTML holds them all, for a reader without script and for a search engine, and the filter applies the moment the page is live. The front page hands the finder the address's tag:"});_e3395.appendChild(_e3491);const _e3492=Component_CodeBlock({code:"// src/pages/Home.wf\n        // `query.tag` is the URL's `?tag=…`; it is missing when the URL has\n        // none, and `?? \"\"` turns that into the finder's \"every note\".\n        NoteFinder(notes, tag: query.tag ?? \"\")",title:"wf"});_e3395.appendChild(_e3492);const _e3493=WF.el("h3",{className:"wf-heading",id:"step-6-a-page-per-note"},"Step 6: a page per note");_e3395.appendChild(_e3493);const _e3494=Component_CodeBlock({code:"// src/pages/NotePage.wf\npage NotePage(path: \"/notes/:slug\", slug: String,\n    title: \"{notes.find(n => n.slug == slug)?.title ?? slug} — Field Notes\",\n    description: \"{notes.find(n => n.slug == slug)?.summary ?? slug}\",\n    type: \"article\",\n    layout: Sheet,\n    paths: notes.map(n => n.slug)) {\n\n    derived note = notes.find(n => n.slug == slug)",title:"wf"});_e3395.appendChild(_e3494);const _e3495=WF.el("div",{className:"wf-markdown",markdown:"`:slug` in the path is a typed parameter of the page. `paths:` names the values a static build renders it for — one `notes/<slug>/index.html` per note, each listed in the sitemap ([Content](/docs/guide/content)). `title:` and `description:` may compute from the parameters, so each note's search result shows its own title and summary. The body is the note's Markdown:"});_e3395.appendChild(_e3495);const _e3496=Component_CodeBlock({code:"// src/pages/NotePage.wf\n            Markdown(n.body)",title:"wf"});_e3395.appendChild(_e3496);const _e3497=WF.el("div",{className:"wf-markdown",markdown:"`Markdown` renders headings, lists, quotes, emphasis and links, at build time and live; the text is escaped first, so HTML in a note is shown, not run ([Elements](/docs/guide/elements)). Below it, `related` is the three newest notes that share a tag — a `derived` value like any other."});_e3395.appendChild(_e3497);const _e3498=WF.el("h3",{className:"wf-heading",id:"step-7-tags-and-a-page-written-in-markdown"},"Step 7: tags, and a page written in Markdown");_e3395.appendChild(_e3498);const _e3499=Component_CodeBlock({code:"// src/pages/Tags.wf\n        Grid(columns: { base: 1, md: 2 }, gap: .md, align: .start) {\n            for tag in allTags by tag {\n                derived filed = notes.filter(n => n.tags.includes(tag)).sortBy(n => n.date).reverse()",title:"wf"});_e3395.appendChild(_e3499);const _e3500=WF.el("div",{className:"wf-markdown",markdown:"A layout prop takes one value per breakpoint — one column on a phone, two from `md` up — compiled to a media query, so the first paint is right ([Styling](/docs/guide/styling)). A `derived` value inside a `for` is worked out per item.\n\nThe About page is not a `.wf` file at all: `src/about.md` is a page, its front matter naming its path, title, description and layout:"});_e3395.appendChild(_e3500);const _e3501=Component_CodeBlock({code:"---\npath: /about\ntitle: About — Field Notes\ndescription: Who keeps this notebook, why it exists, and how the site is built.\nlayout: Sheet\n---\n# About",title:"markdown"});_e3395.appendChild(_e3501);const _e3502=WF.el("h3",{className:"wf-heading",id:"step-8-the-reader-s-saved-notes"},"Step 8: the reader's saved notes");_e3395.appendChild(_e3502);const _e3503=Component_CodeBlock({code:"// src/stores/Saved.wf\n/// The notes this reader has saved for later, kept in their browser.\nstore Saved {\n    persist slugs: [String] = []\n\n    derived count = slugs.length",title:"wf"});_e3395.appendChild(_e3503);const _e3504=WF.el("div",{className:"wf-markdown",markdown:"`persist` keeps the list in the browser across visits — there is no account and nothing is sent anywhere ([Stores](/docs/guide/stores)). The button that saves a note says whether it is pressed, the way assistive technology reads it:"});_e3395.appendChild(_e3504);const _e3505=Component_CodeBlock({code:"// src/components/SaveButton.wf\n/// Saves a note for later, or takes it off the saved list.\ncomponent SaveButton(_ slug: String, title: String) {\n    use Saved\n\n    Button(if Saved.slugs.includes(slug) { \"Saved\" } else { \"Save\" },\n        aria-pressed: Saved.slugs.includes(slug),\n        aria-label: if Saved.slugs.includes(slug) { \"Saved: {title}\" } else { \"Save: {title}\" },\n        class: \"save-button\").sm.outlined {\n        on click { Saved.toggle(slug) }\n    }\n}",title:"wf"});_e3395.appendChild(_e3505);const _e3506=WF.el("div",{className:"wf-markdown",markdown:"`aria-pressed` follows the state, and `styles.css` styles the pressed button with `[aria-pressed=\"true\"]` — the look and the meaning are one attribute ([Accessibility](/docs/guide/accessibility)). The Saved page lists `notes.filter(n => Saved.slugs.includes(n.slug))`, and the navbar's badge is `Saved.count`."});_e3395.appendChild(_e3506);const _e3507=WF.el("h3",{className:"wf-heading",id:"step-9-tests-and-the-checks-a-static-site-deserves"},"Step 9: tests, and the checks a static site deserves");_e3395.appendChild(_e3507);const _e3508=Component_CodeBlock({code:"// tests/NoteFinder.wf\ntest \"a search that matches nothing says so, and clears\" {\n    NoteFinder(notes)\n    type \"zeppelin\" into \"Search the notes\"\n    expect \"Nothing matches\"\n    expect \"0 of 7 notes\"\n    click \"Clear the search\"\n    expect \"7 of 7 notes\"\n    expect not \"Nothing matches\"\n}",title:"wf"});_e3395.appendChild(_e3508);const _e3509=WF.el("div",{className:"wf-markdown",markdown:"A test reads the project's `data` file like any page does ([Testing](/docs/guide/testing)). Then:"});_e3395.appendChild(_e3509);const _e3510=Component_Terminal({lines:[({command:"wf test",output:""}),({command:"wf check --deny-warnings",output:""}),({command:"wf build",output:""}),({command:"wf verify",output:""})]});_e3395.appendChild(_e3510);const _e3511=WF.el("div",{className:"wf-markdown",markdown:"`wf verify` loads every route of the built site in a headless Chrome — each note's page at its `paths:` value — and fails on an error, a missing file or a page that draws nothing ([Command line](/docs/guide/cli)). `build/` is ready for any static host."});_e3395.appendChild(_e3511);const _e3512=WF.el("h2",{className:"wf-heading",id:"hard-pocket"},"Hard: Pocket");_e3395.appendChild(_e3512);const _e3513=WF.el("div",{className:"wf-markdown",markdown:"A personal budget tracker that lives entirely in the reader's browser: money in and money out, a budget per category, what is left of it this month, six months of bars, two languages, a CSV out and back in, and a page that keeps working offline. No server and no account. A couple of hours; it assumes the easy tutorial, and every step links the chapter that goes deeper. The finished project is [`examples/tutorials/hard-pocket`](https://github.com/monzeromer-lab/WebFluent/tree/master/examples/tutorials/hard-pocket)."});_e3395.appendChild(_e3513);const _e3514=WF.el("h3",{className:"wf-heading",id:"step-1-a-project"},"Step 1: a project");_e3395.appendChild(_e3514);const _e3515=Component_CodeBlock({code:"{\n  \"name\": \"pocket\",\n  \"version\": \"1.0.0\",\n  \"author\": \"WebFluent tutorials\",\n  \"theme\": { \"name\": \"Pocket\", \"dark\": \"PocketNight\" },\n  \"build\": {\n    \"output\": \"./build\",\n    \"output_type\": \"spa\",\n    \"csp\": true\n  },\n  \"meta\": {\n    \"title\": \"Pocket\",\n    \"description\": \"A budget that lives in your browser: income, spending and what is left, month by month.\",\n    \"lang\": \"en\"\n  },\n  \"i18n\": {\n    \"default_locale\": \"en\",\n    \"locales\": [\"en\", \"ar\"],\n    \"dir\": \"src/translations\"\n  },\n  \"offline\": {\n    \"precache\": [\"/\", \"/entries\", \"/categories\", \"/settings\"],\n    \"fallback\": \"/\"\n  }\n}",title:"json"});_e3395.appendChild(_e3515);const _e3516=WF.el("div",{className:"wf-markdown",markdown:"Three settings this project adds to the easy one: `i18n` names the languages and where their messages live ([Internationalization](/docs/guide/i18n)); `offline` makes `wf build` write a service worker that stores the four pages, so a second visit opens with no network ([Offline](/docs/guide/offline)); and the two themes, light and dark, both of which the build ships."});_e3395.appendChild(_e3516);const _e3517=WF.el("h3",{className:"wf-heading",id:"step-2-what-money-is"},"Step 2: what money is");_e3395.appendChild(_e3517);const _e3518=Component_CodeBlock({code:"// src/types.wf\n/// Which way the money went.\nenum Kind { income, expense }\n\n/// Something money is spent on, with what the reader means to spend on it\n/// in a month.\ntype Category {\n    id: String\n    name: String\n    color: Color\n    budget: Money\n}\n\n/// One line of the ledger: money in, or money out.\ntype Entry {\n    id: Uuid\n    date: Date\n    amount: Money\n    kind: Kind\n    category: String\n    note: String = \"\"\n}",title:"wf"});_e3395.appendChild(_e3518);const _e3519=WF.el("div",{className:"wf-markdown",markdown:"`Money`, `Date`, `Color` and `Uuid` are types the language brings, each a plain JSON value at run time ([Types](/docs/guide/types)). Money is kept in minor units, `{ amount: 1299, currency: \"USD\" }`, so a sum never drifts by a fraction of a cent; it is written `$12.99` and shown with `format(m)`. Its methods are calls — `a.plus(b)`, `a.minus(b)`, `ONE.times(12.5)` — and its carrier's fields are fields: `m.amount`."});_e3395.appendChild(_e3519);const _e3520=Component_CodeBlock({code:"// src/types.wf\n/// Nothing yet: the starting point every sum adds to.\nconst ZERO: Money = $0.00\n\n/// One dollar — `ONE.times(12.5)` is $12.50, rounded to the cent.\nconst ONE: Money = $1.00",title:"wf"});_e3395.appendChild(_e3520);const _e3521=WF.el("h3",{className:"wf-heading",id:"step-3-a-ledger-that-adds-itself-up"},"Step 3: a ledger that adds itself up");_e3395.appendChild(_e3521);const _e3522=Component_CodeBlock({code:"// src/stores/Ledger.wf\n    derived today = now.date()\n    derived newestFirst = entries.sortBy(e => e.date).reverse()\n\n    derived income = sum(entries.filter(e => e.kind == .income))\n    derived spent = sum(entries.filter(e => e.kind == .expense))\n    derived balance = income.minus(spent)\n\n    derived thisMonth = entries.filter(e => e.date.startOfMonth().isSame(today.startOfMonth()))\n    derived monthIncome = sum(thisMonth.filter(e => e.kind == .income))\n    derived monthSpent = sum(thisMonth.filter(e => e.kind == .expense))\n    derived monthBudget = categories.reduce((s, c) => s.plus(c.budget), ZERO)\n    derived budgetLeft = monthBudget.minus(monthSpent)",title:"wf"});_e3395.appendChild(_e3522);const _e3523=WF.el("div",{className:"wf-markdown",markdown:"Every figure on every page is a `derived` value of the store: add an entry and the balance, this month's spending, each budget bar and the chart all follow, with nothing written to keep them in step ([Stores](/docs/guide/stores)). `now` is the browser's clock as a value, so `today` turns over at midnight. `sum` is an action that only returns a value, which a derived value may call:"});_e3395.appendChild(_e3523);const _e3524=Component_CodeBlock({code:"// src/stores/Ledger.wf\n    // The money in a list of entries, added up.\n    action sum(list: [Entry]) {\n        return list.reduce((total, e) => total.plus(e.amount), ZERO)\n    }",title:"wf"});_e3395.appendChild(_e3524);const _e3525=WF.el("h3",{className:"wf-heading",id:"step-4-changing-the-shape-without-losing-anyone-s-data"},"Step 4: changing the shape without losing anyone's data");_e3395.appendChild(_e3525);const _e3526=Component_CodeBlock({code:"// src/stores/Ledger.wf\n    // Version 1 of Pocket kept an amount as a plain, signed number of\n    // dollars (`-52.4` was money out). Version 2 keeps a `Money` and a\n    // `Kind`, so `migrate 1 -> 2` turns what a returning reader's browser\n    // holds into the new shape instead of throwing it away.\n    persist entries: [Entry] = SAMPLE_ENTRIES.map(s => Entry(\n            id: s.id,\n            date: now.date().minus(days: s.ago),\n            amount: s.amount,\n            kind: s.kind,\n            category: s.category,\n            note: s.note,\n        )) {\n        version: 2\n        migrate 1 -> 2 {\n            old.map(e => Entry(\n                    id: e.id,\n                    date: e.date,\n                    amount: ONE.times(Math.abs(e.amount)),\n                    kind: if e.amount < 0 { .expense } else { .income },\n                    category: e.category,\n                    note: e.note ?? \"\",\n                ))\n        }\n    }",title:"wf"});_e3395.appendChild(_e3526);const _e3527=WF.el("div",{className:"wf-markdown",markdown:"What a `persist` keeps outlives the build that wrote it: a reader who visited last month has last month's shape in their browser. `version: 2` says what this build writes; `migrate 1 -> 2` brings an older value forward, given as `old`. Raise the version without a migration and the build warns (`P01`); change the shape without raising it and it warns too (`D04`), from the shapes it keeps in `.wf-cache/` ([Stores](/docs/guide/stores)). A first visit opens on a sample ledger dated from today, so the dashboard is never empty."});_e3395.appendChild(_e3527);const _e3528=WF.el("h3",{className:"wf-heading",id:"step-5-a-shell-that-fits-the-screen"},"Step 5: a shell that fits the screen");_e3395.appendChild(_e3528);const _e3529=Component_CodeBlock({code:"// src/App.wf\n            if Ui.menuOpen {\n                Host(tag: \"div\", class: \"scrim\") { on click { Ui.closeAll() } }\n                Stack(gap: .md, class: \"drawer\", animate: .slideRight, exit: .fadeOut) {\n                    on click { Ui.menuOpen = false }\n                    Brand\n                    NavLinks\n                }\n            }",title:"wf"});_e3395.appendChild(_e3529);const _e3530=WF.el("div",{className:"wf-markdown",markdown:"The shell draws a `Sidebar` when `viewport.lg` holds and a top bar with this drawer when it does not. `viewport` is the window's size as a value, following `matchMedia`, so the switch happens once as the window crosses the breakpoint ([Styling](/docs/guide/styling)). The layout itself — grids that are one column on a phone — is responsive values, `Grid(columns: { base: 1, lg: 2 })`, which need no script. A second store, `Ui`, holds what the interface is doing — the dialog, the menu, the notices — apart from what the ledger holds."});_e3395.appendChild(_e3530);const _e3531=WF.el("h3",{className:"wf-heading",id:"step-6-a-dashboard-drawn-from-elements"},"Step 6: a dashboard drawn from elements");_e3395.appendChild(_e3531);const _e3532=Component_CodeBlock({code:"// src/components/MonthChart.wf\n/// Six months of money in and money out, as pairs of bars.\n///\n/// The built-in `Chart` draws at build time, from data the build can see.\n/// This ledger only exists in the reader's browser, so the chart is made of\n/// plain elements whose heights follow the store: `height: {share}%` is a\n/// style value that reads state, and repaints when it changes.\ncomponent MonthChart(months: [MonthTotal], top: Number) {\n    Stack(gap: .sm) {\n        Row(class: \"chart\", align: .end, role: \"img\", aria-label: t(\"chart.label\")) {\n            for m in months by m.month {\n                Stack(gap: .xs, align: .center, class: \"chart__month\") {\n                    Row(gap: .xs, align: .end, class: \"chart__bars\") {\n                        Host(tag: \"span\", class: \"chart__bar chart__bar--in\") {\n                            style { height: {m.income.amount / top * 100}% }\n                        }\n                        Host(tag: \"span\", class: \"chart__bar chart__bar--out\") {\n                            style { height: {m.spent.amount / top * 100}% }\n                        }\n                    }",title:"wf"});_e3395.appendChild(_e3532);const _e3533=WF.el("div",{className:"wf-markdown",markdown:"A `{…}` in a style value reads state, and the property follows it ([Styling](/docs/guide/styling)). The chart is one `role=\"img\"` with a label, so a screen reader hears what it shows rather than twelve unnamed boxes ([Accessibility](/docs/guide/accessibility)). The figures above it are one component placed four times:"});_e3395.appendChild(_e3533);const _e3534=Component_CodeBlock({code:"// src/pages/Dashboard.wf\n    Grid(columns: { base: 2, xl: 4 }, gap: .md) {\n        KpiCard(t(\"kpi.balance\"), value: Ledger.balance, note: t(\"kpi.balanceNote\"))\n        KpiCard(t(\"kpi.income\"), value: Ledger.monthIncome, note: t(\"kpi.thisMonth\"), lean: .good)\n        KpiCard(t(\"kpi.spent\"), value: Ledger.monthSpent, note: t(\"kpi.thisMonth\"), lean: .bad)\n        KpiCard(t(\"kpi.left\"), value: Ledger.budgetLeft, note: t(\"kpi.leftNote\", { budget: format(Ledger.monthBudget) }),\n            lean: if Ledger.budgetLeft.amount < 0 { .bad } else { .good })\n    }",title:"wf"});_e3395.appendChild(_e3534);const _e3535=WF.el("div",{className:"wf-markdown",markdown:"`lean` is an enum prop, and a component's enum props are written to its root element as `data-lean=\"good\"`, which `pocket.css` colours by ([Components](/docs/guide/components))."});_e3395.appendChild(_e3535);const _e3536=WF.el("h3",{className:"wf-heading",id:"step-7-filters-in-the-address"},"Step 7: filters in the address");_e3395.appendChild(_e3536);const _e3537=Component_CodeBlock({code:"// src/pages/Entries.wf\n    // The filters live in the address — `/entries?month=2026-09&category=dining` —\n    // so they survive a reload, a shared link and the back button.\n    derived month = query.month ?? \"\"\n    derived category = query.category ?? \"\"\n    derived shown = Ledger.newestFirst.filter(e => (month == \"\" || e.date.slice(0, 7) == month) && (category == \"\" || e.category == category))",title:"wf"});_e3395.appendChild(_e3537);const _e3538=WF.el("div",{className:"wf-markdown",markdown:"Choosing a month calls `navigate(\"/entries?month=…\")`; the address changes, `query` follows it, and so does the list. An entry has a page of its own at `/entries/:id`, where `id` is a typed parameter; the page looks the entry up with `Ledger.entries.find(…)` and draws it inside `if let e = entry` — `if let` binds the value only when it is there, which the checker requires before reading its fields ([Pages and routing](/docs/guide/pages-and-routing))."});_e3395.appendChild(_e3538);const _e3539=WF.el("h3",{className:"wf-heading",id:"step-8-one-form-for-new-and-for-edit"},"Step 8: one form for new and for edit");_e3395.appendChild(_e3539);const _e3540=Component_CodeBlock({code:"// src/components/EntryForm.wf\n/// The form for a new entry — or, given one, for changing it. It checks what\n/// the reader typed, writes it to the ledger, and says so with `saved`.\ncomponent EntryForm(entry: Entry? = null) {\n    use Ledger\n    event saved()\n\n    state kind: Kind = entry?.kind ?? .expense\n    state amount: Number? = if let e = entry { e.amount.amount / 100 } else { null }\n    state date: Date? = entry?.date ?? Ledger.today\n    state category = entry?.category ?? \"groceries\"\n    state note = entry?.note ?? \"\"\n\n    validate amount {\n        required\n        min(0.01)\n    }\n    // Not in the future. With no message of its own, the rule shows the\n    // translation of `form.max`; `Ledger.today` is read each time it checks.\n    validate date {\n        required\n        max(Ledger.today)\n    }\n    validate note { maxLength(60) }",title:"wf"});_e3395.appendChild(_e3540);const _e3541=WF.el("div",{className:"wf-markdown",markdown:"A `validate` block sits beside the state it guards, and the control bound to that state shows what the rules say — the message, `aria-invalid`, the link between them — with nothing written ([Forms](/docs/guide/forms)). A rule without a message of its own shows the translation of `form.<rule>`, so `en.json` and `ar.json` each say \"that date has not happened yet\" once. The form says when it is done with an event; the caller decides what that means — close the dialog, or go back to the entry:"});_e3395.appendChild(_e3541);const _e3542=Component_CodeBlock({code:"// src/components/EntryForm.wf\n        Row(justify: .end, gap: .sm) {\n            Button(if entry != null { t(\"action.save\") } else { t(\"action.add\") }, type: .submit, disabled: !form.valid).primary\n        }",title:"wf"});_e3395.appendChild(_e3542);const _e3543=WF.el("div",{className:"wf-markdown",markdown:"`Form(bind: form)` hands a handle on the form; `form.valid` is whether every rule holds, and the button follows it as the reader types."});_e3395.appendChild(_e3543);const _e3544=WF.el("h3",{className:"wf-heading",id:"step-9-a-dialog-and-a-shortcut"},"Step 9: a dialog and a shortcut");_e3395.appendChild(_e3544);const _e3545=Component_CodeBlock({code:"// src/App.wf\n    // `n` opens a new entry from anywhere. A key with no modifier is left to\n    // the field the reader is typing in, so an `n` in a note is just a letter.\n    on key(\"n\") { Ui.compose() }\n    on key(\"Escape\") { Ui.closeAll() }",title:"wf"});_e3395.appendChild(_e3545);const _e3546=WF.el("div",{className:"wf-markdown",markdown:"`on key` at the top of the app listens on the document for as long as the page shows ([Events](/docs/guide/events)). The dialog is a `Modal` whose `title:` is its accessible name; it traps focus while open, and `Escape` closes it:"});_e3395.appendChild(_e3546);const _e3547=Component_CodeBlock({code:"// src/App.wf\n    Modal(visible: Ui.composing, title: t(\"compose.title\")) {\n        if Ui.composing {\n            EntryForm {\n                on saved {\n                    Ui.composing = false\n                    Ui.notify(t(\"toast.added\"))\n                }\n            }\n        }\n    }",title:"wf"});_e3395.appendChild(_e3547);const _e3548=WF.el("h3",{className:"wf-heading",id:"step-10-two-languages"},"Step 10: two languages");_e3395.appendChild(_e3548);const _e3549=Component_CodeBlock({code:"{\n  \"entries.zero\": \"No entries\",\n  \"entries.one\": \"{count} entry\",\n  \"entries.other\": \"{count} entries\"\n}",title:"json"});_e3395.appendChild(_e3549);const _e3550=WF.el("div",{className:"wf-markdown",markdown:"Every word on screen is `t(\"key\")`, read from `src/translations/en.json` or `ar.json`. A message with plural forms is several keys, and `t(\"entries\", { count: n })` picks the form the language's rules call for — Arabic has six ([Internationalization](/docs/guide/i18n)). Switching to Arabic sets `dir=\"rtl\"` on the page, and the sidebar, the rows and the grids mirror themselves. `format(m)` and dates follow the language too. The reader's choice is a `persist` in a small `Prefs` store, applied on every visit by an `effect` in the app shell."});_e3395.appendChild(_e3550);const _e3551=WF.el("h3",{className:"wf-heading",id:"step-11-your-data-out-and-back-in"},"Step 11: your data out, and back in");_e3395.appendChild(_e3551);const _e3552=Component_CodeBlock({code:"// src/pages/Settings.wf\n    action exportCsv() {\n        let lines = Ledger.newestFirst.map(e => csvLine(e))\n        saveTextFile(\"pocket-{Ledger.today}.csv\", [CSV_HEADER, ...lines].join(\"\\n\"), \"text/csv\")\n    }",title:"wf"});_e3395.appendChild(_e3552);const _e3553=WF.el("div",{className:"wf-markdown",markdown:"`saveTextFile` is not WebFluent: it is a function in `src/files.js`, a plain browser script the build links on every page and whose JSDoc types the call, so `saveTextFile(1)` is an error where it is written ([JavaScript interop](/docs/guide/interop)). Importing reads a file from a `FileUpload` with `await f.text()`, parses each line, and merges what is new; then it tells every other open tab:"});_e3395.appendChild(_e3553);const _e3554=Component_CodeBlock({code:"// src/pages/Settings.wf\n        let added = Ledger.merge(parsed)\n        news.post({ count: added })",title:"wf"});_e3395.appendChild(_e3554);const _e3555=WF.el("div",{className:"wf-markdown",markdown:"`news` is `channel news = broadcast(\"pocket\")`, a channel every tab of the site hears; the app shell listens on it and shows a toast ([Realtime](/docs/guide/realtime)). The ledger itself needs no channel — `persist` already keeps every tab in step."});_e3395.appendChild(_e3555);const _e3556=WF.el("h3",{className:"wf-heading",id:"step-12-tests-and-the-checks"},"Step 12: tests, and the checks");_e3395.appendChild(_e3556);const _e3557=Component_CodeBlock({code:"// tests/pocket.wf\ntest \"an entry added through the form moves the balance\" {\n    use Ledger\n    Text(\"Balance {format(Ledger.balance)}\")\n    EntryForm\n\n    expect \"Balance $16,533.56\"\n    click \"Money in\"\n    type \"250\" into \"Amount\"\n    click \"Add entry\"\n    expect \"Balance $16,783.56\"",title:"wf"});_e3395.appendChild(_e3557);const _e3558=WF.el("div",{className:"wf-markdown",markdown:"The test drives the real form by the labels a reader sees — the English ones, since a test reads the project's default locale — in a headless Chrome ([Testing](/docs/guide/testing)). Pocket has eight: the cards and rows render what they should, a blank amount is refused, `n` opens the dialog and `Escape` closes it, removing an entry takes it out of every total."});_e3395.appendChild(_e3558);const _e3559=Component_Terminal({lines:[({command:"wf test",output:""}),({command:"wf check --deny-warnings",output:""}),({command:"wf build",output:""}),({command:"wf verify",output:""})]});_e3395.appendChild(_e3559);const _e3560=WF.el("div",{className:"wf-markdown",markdown:"`build/` is a single-page app with a service worker beside it: put it on a host that serves `index.html` for every path ([Deploying](/docs/guide/deploying)), and the second visit works on a plane."});_e3395.appendChild(_e3560);const _e3561=WF.el("h2",{className:"wf-heading",id:"recipes"},"Recipes");_e3395.appendChild(_e3561);const _e3562=WF.el("div",{className:"wf-markdown",markdown:"Smaller pieces every project meets, each a block you can drop into a page."});_e3395.appendChild(_e3562);const _e3563=WF.el("h3",{className:"wf-heading",id:"debounced-search"},"Debounced search");_e3395.appendChild(_e3563);const _e3564=Component_CodeBlock({code:"page Search(path: \"/\") {\n    state typed = \"\"\n    state q = \"\"\n    action commit(value: String) { if value == typed { q = value } }\n    effect {\n        let pending = typed\n        setTimeout(() => commit(pending), 300)\n    }\n    resource hits = fetch(\"/api/search?q={q}\")\n    Input(bind: typed, placeholder: \"Search\", aria-label: \"Search\")\n    match hits {\n        loading { Spinner.sm }\n        error(e) { Text(e.message).danger }\n        ready(list) { Text(\"{list.length} results for {q}\") }\n    }\n}",title:"wf"});_e3395.appendChild(_e3564);const _e3565=WF.el("div",{className:"wf-markdown",markdown:"The effect re-runs on every keystroke; each run schedules a check, and only the one whose value is still current commits to `q`, which the resource follows. (`after(ms)` is a declaration of a body, not a statement, so a timer inside an effect is the browser's `setTimeout`.)"});_e3395.appendChild(_e3565);const _e3566=WF.el("h3",{className:"wf-heading",id:"pagination"},"Pagination");_e3395.appendChild(_e3566);const _e3567=Component_CodeBlock({code:"page Rows(path: \"/\") {\n    state page = 1\n    state perPage = 20\n    resource rows = fetch(\"/api/rows?page={page}&per={perPage}\")\n    match rows {\n        loading { Spinner }\n        error(e) { Text(e.message).danger }\n        ready(r) {\n            for row in r.items by row.id { Text(row.name) }\n            Row(gap: .sm, align: .center) {\n                Button(\"Previous\", disabled: page == 1) { on click { page = page - 1 } }\n                Text(\"Page {page} of {r.pages}\")\n                Button(\"Next\", disabled: page >= r.pages) { on click { page = page + 1 } }\n            }\n        }\n    }\n}",title:"wf"});_e3395.appendChild(_e3567);const _e3568=WF.el("h3",{className:"wf-heading",id:"optimistic-update-with-rollback"},"Optimistic update with rollback");_e3395.appendChild(_e3568);const _e3569=Component_CodeBlock({code:"type Item { id: String, liked: Bool }\n\npage Likes(path: \"/\") {\n    state items: [Item] = [Item(id: \"a\", liked: false)]\n    state error = \"\"\n    action like(id: String) {\n        let before = items\n        items = items.map(i => if i.id == id { Item(id: i.id, liked: !i.liked) } else { i })\n        try {\n            await fetch(\"/api/like/{id}\", { method: \"POST\" })\n        } catch e {\n            items = before\n            error = \"Could not save. Try again.\"\n        }\n    }\n    for i in items by i.id {\n        Button(if i.liked { \"♥\" } else { \"♡\" }, aria-label: \"Like\").sm { on click { like(i.id) } }\n    }\n    if error != \"\" { Toast(error).danger }\n}",title:"wf"});_e3395.appendChild(_e3569);const _e3570=WF.el("h3",{className:"wf-heading",id:"a-confirm-dialog-component"},"A confirm dialog component");_e3395.appendChild(_e3570);const _e3571=Component_CodeBlock({code:"component Confirm(_ title: String, visible: Bool, danger: Bool = false) {\n    event confirm()\n    event cancel()\n    slot\n    Dialog(visible: visible, title: title) {\n        children\n        Row(gap: .sm, justify: .end) {\n            Button(\"Cancel\") { on click { emit cancel() } }\n            Button(\"Confirm\", tone: if danger { .danger } else { .primary }) { on click { emit confirm() } }\n        }\n    }\n}\n\npage Use(path: \"/\") {\n    state asking = false\n    state gone = false\n    Button(\"Delete account\").danger { on click { asking = true } }\n    Confirm(\"Delete your account?\", visible: asking, danger: true) {\n        on confirm { gone = true  asking = false }\n        on cancel { asking = false }\n        Text(\"Everything goes. This cannot be undone.\")\n    }\n    if gone { Alert(\"Account deleted.\").info }\n}",title:"wf"});_e3395.appendChild(_e3571);const _e3572=WF.el("h3",{className:"wf-heading",id:"responsive-navigation"},"Responsive navigation");_e3395.appendChild(_e3572);const _e3573=Component_CodeBlock({code:"page Nav(path: \"/\") {\n    state open = false\n    if viewport.md {\n        Row(gap: .md) {\n            Link(\"Home\", to: \"/\")\n            Link(\"Docs\", to: \"/docs\")\n            Link(\"Pricing\", to: \"/pricing\")\n        }\n    } else {\n        IconButton(icon: \"menu\", label: \"Open navigation\") { on click { open = !open } }\n        show open {\n            Stack(gap: .sm, animate: .slideDown) {\n                Link(\"Home\", to: \"/\")\n                Link(\"Docs\", to: \"/docs\")\n                Link(\"Pricing\", to: \"/pricing\")\n            }\n        }\n    }\n}",title:"wf"});_e3395.appendChild(_e3573);const _e3574=WF.el("h3",{className:"wf-heading",id:"a-form-with-validation-messages"},"A form with validation messages");_e3395.appendChild(_e3574);const _e3575=Component_CodeBlock({code:"page Signup(path: \"/\") {\n    state email = \"\"\n    state password = \"\"\n    state confirm = \"\"\n    state sent = false\n    validate email { required  email \"Enter a valid email\" }\n    validate password { required  minLength(8) \"At least 8 characters\" }\n    validate confirm { matches(password) \"The passwords differ\" }\n    Form(bind: form) {\n        on submit { sent = true  form.reset() }\n        Input(bind: email, name: \"email\", label: \"Email\").email\n        Input(bind: password, name: \"password\", label: \"Password\").password\n        Input(bind: confirm, name: \"confirm\", label: \"Confirm password\").password\n        Button(\"Create account\", type: .submit, disabled: !form.valid).primary\n    }\n    if sent { Alert(\"Welcome aboard.\").success }\n}",title:"wf"});_e3395.appendChild(_e3575);const _e3576=WF.el("div",{className:"wf-markdown",markdown:"Each control shows its own message when the reader leaves it, and a submit that fails focuses the first problem. [Forms](/docs/guide/forms) has every rule."});_e3395.appendChild(_e3576);const _e3577=WF.el("h3",{className:"wf-heading",id:"tabs-with-the-active-tab-in-the-url"},"Tabs with the active tab in the URL");_e3395.appendChild(_e3577);const _e3578=Component_CodeBlock({code:"page Account(path: \"/account\") {\n    derived tab = if hash != \"\" { hash } else { \"profile\" }\n    Row(gap: .sm) {\n        Link(\"Profile\", to: \"/account#profile\")\n        Link(\"Billing\", to: \"/account#billing\")\n    }\n    if tab == \"profile\" { Text(\"Profile settings\") }\n    if tab == \"billing\" { Text(\"Billing settings\") }\n}",title:"wf"});_e3395.appendChild(_e3578);const _e3579=WF.el("h3",{className:"wf-heading",id:"reading-a-store-from-a-component-without-use"},"Reading a store from a component without use");_e3395.appendChild(_e3579);const _e3580=WF.el("div",{className:"wf-markdown",markdown:"A component that only needs one value takes it as a prop, which keeps it reusable outside that store:"});_e3395.appendChild(_e3580);const _e3581=Component_CodeBlock({code:"store Cart { state count = 0 }\n\ncomponent CartBadge(count: Number) {\n    if count > 0 { Badge(\"{count}\").primary }\n}\n\npage Shop(path: \"/\") {\n    use Cart\n    CartBadge(count: Cart.count)\n}",title:"wf"});_e3395.appendChild(_e3581);const _e3582=WF.el("h3",{className:"wf-heading",id:"countdown"},"Countdown");_e3395.appendChild(_e3582);const _e3583=Component_CodeBlock({code:"page Countdown(path: \"/\") {\n    state left = 10\n    every(1000) { if left > 0 { left = left - 1 } }\n    Progress(value: 10 - left, max: 10)\n    Text(if left == 0 { \"Done\" } else { \"{left}s\" })\n}",title:"wf"});_e3395.appendChild(_e3583);const _e3584=WF.el("h3",{className:"wf-heading",id:"signing-in-with-a-session-cookie"},"Signing in with a session cookie");_e3395.appendChild(_e3584);const _e3585=Component_CodeBlock({code:"type User { id: String, name: String }\n\napi Auth(base: \"/api\") {\n    credentials: .sameOrigin\n    get me() -> User\n    post signIn(body: Map) -> User\n        errors { 401 -> Map }\n    post signOut()\n}\n\nstore Session {\n    state user: User? = null\n    state checked = false\n    derived signedIn = user != null\n    action load() {\n        try { user = await Auth.me() } catch e { user = null }\n        checked = true\n    }\n    action signIn(email: String, password: String) {\n        user = await Auth.signIn(body: { email: email, password: password })\n        navigate(\"/account\")\n    }\n    action signOut() {\n        await Auth.signOut()\n        user = null\n        navigate(\"/\")\n    }\n}\n\npage SignIn(path: \"/sign-in\", title: \"Sign in\", description: \"Sign in to your account.\", noindex: true) {\n    state email = \"\"\n    state password = \"\"\n    state problem = \"\"\n    validate email { required  email }\n    validate password { required }\n    action send() {\n        problem = \"\"\n        try { await Session.signIn(email, password) } catch e { problem = \"That email and password do not match.\" }\n    }\n    Heading(\"Sign in\").h1\n    if problem != \"\" { Alert(problem).danger }\n    Form(bind: form) {\n        on submit { send() }\n        Input(bind: email, label: \"Email\").email\n        Input(bind: password, label: \"Password\").password\n        Button(\"Sign in\", type: .submit, disabled: send.pending).primary\n    }\n}\n\npage Account(path: \"/account\", title: \"Your account\", description: \"Your account.\", guard: Session.signedIn, redirect: \"/sign-in\") {\n    use Session\n    Heading(\"Your account\").h1\n    if let u = Session.user { Text(\"Signed in as {u.name}\") }\n    Button(\"Sign out\") { on click { Session.signOut() } }\n}",title:"wf"});_e3395.appendChild(_e3585);const _e3586=WF.el("div",{className:"wf-markdown",markdown:"The session is an httpOnly cookie the server sets; the page never holds a token. `guard:` hides the page from the signed-out, and the server still checks every request ([Security](/docs/guide/security#sessions-and-tokens)). Call `Session.load()` from the app's set-up so a returning reader is signed in."});_e3395.appendChild(_e3586);const _e3587=WF.el("h3",{className:"wf-heading",id:"load-more"},"Load more");_e3395.appendChild(_e3587);const _e3588=Component_CodeBlock({code:"type Item { id: String, name: String }\n\napi Catalog(base: \"/api\") {\n    get items(page: Number = 1) -> [Item]\n}\n\npage Items(path: \"/items\", title: \"Items\", description: \"Everything, a page at a time.\") {\n    state page = 1\n    resource list = Catalog.items(page: page, paginate: .page)\n    Heading(\"Items\").h1\n    for item in list.items by item.id { Text(item.name) }\n    if list.hasMore {\n        Button(\"Load more\", disabled: list.state == \"loading\") { on click { list.loadMore() } }\n    }\n}",title:"wf"});_e3395.appendChild(_e3588);const _e3589=WF.el("h3",{className:"wf-heading",id:"filters-in-the-url"},"Filters in the URL");_e3395.appendChild(_e3589);const _e3590=Component_CodeBlock({code:"page Products(path: \"/products\", title: \"Products\", description: \"Everything we sell.\") {\n    derived sort = query.sort ?? \"name\"\n    Heading(\"Products\").h1\n    Row(gap: .sm) {\n        Link(\"By name\", to: \"/products?sort=name\")\n        Link(\"By price\", to: \"/products?sort=price\")\n    }\n    Text(\"Sorted by {sort}\")\n}",title:"wf"});_e3395.appendChild(_e3590);const _e3591=WF.el("div",{className:"wf-markdown",markdown:"A filter in the query string survives a reload, a shared link and the back button, where a `state` would not."});_e3395.appendChild(_e3591);const _e3592=WF.el("h3",{className:"wf-heading",id:"a-dark-mode-switch"},"A dark-mode switch");_e3395.appendChild(_e3592);const _e3593=Component_CodeBlock({code:"page Settings(path: \"/settings\", title: \"Settings\", description: \"How the site looks.\") {\n    Heading(\"Settings\").h1\n    Row(gap: .sm) {\n        Button(\"Light\", outlined: theme != \"light\") { on click { setTheme(\"light\") } }\n        Button(\"Dark\", outlined: theme != \"dark\") { on click { setTheme(\"dark\") } }\n        Button(\"Match the system\", outlined: theme != \"system\") { on click { setTheme(\"system\") } }\n    }\n}",title:"wf"});_e3395.appendChild(_e3593);const _e3594=WF.el("div",{className:"wf-markdown",markdown:"It needs a dark theme named in the config ([Styling](/docs/guide/styling#dark-mode))."});_e3395.appendChild(_e3594);const _e3595=WF.el("h3",{className:"wf-heading",id:"copy-to-the-clipboard"},"Copy to the clipboard");_e3395.appendChild(_e3595);const _e3596=Component_CodeBlock({code:"page Share(path: \"/share\", title: \"Share\", description: \"Copy the link.\") {\n    state copied = false\n    action copy(text: String) {\n        await navigator.clipboard.writeText(text)\n        copied = true\n    }\n    Heading(\"Share\").h1\n    Button(\"Copy the link\") { on click { copy(location.href) } }\n    if copied { Toast(\"Copied\").success }\n}",title:"wf"});_e3395.appendChild(_e3596);const _e3597=WF.el("h3",{className:"wf-heading",id:"a-chart"},"A chart");_e3395.appendChild(_e3597);const _e3598=WF.el("div",{className:"wf-markdown",markdown:"A charting library is a URL in `meta.scripts`, called from a script of your own and handed a canvas with `Host`; the full example is in [JavaScript interop](/docs/guide/interop#a-library-from-a-cdn)."});_e3395.appendChild(_e3598);const _e3599=WF.el("h2",{className:"wf-heading",id:"where-to-go-next"},"Where to go next");_e3395.appendChild(_e3599);const _e3600=WF.el("div",{className:"wf-markdown",markdown:"- The [components reference](/docs/reference) for every prop and flag.\n- `examples/` in the repository: the tutorials, reference PDFs and slide decks, and the `tests/fixtures/` projects — a gallery, a dashboard, a docs site, an offline site — each complete.\n- `wf docs` in your own project, for what *your* components take."});_e3395.appendChild(_e3600);_root.appendChild(_e3395);return _root;}
WF.page("TutorialsGuide",Page_TutorialsGuide);